Translate("deDE", "dustwallow-marsh", {
	title = "Marschen von Dustwallow",
	aliases = { "Dustwallow", "Sumpf von Dustwallow" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[{link:the-marshlands}Die Marschen{/link} von Dustwallow sind ein ertrunkenes Land aus schwarzem Wasser, Schilf und Nebel an der Ostküste von {link:kalimdor}Kalimdor{/link}, südlich des {link:the-barrens}Brachlands{/link}. Ihre Straßen versinken im Schlamm, ihre Bäume faulen, wo sie stehen, und in jedem Tümpel liegen Krokilisken. An ihrem östlichen Rand, auf einer Insel in der Bucht, steht die weiße {link:theramore-isle}Stadt Theramore{/link}, eine Zuflucht für die {link:humans}Menschen{/link}, die nach dem Fall von {link:lordaeron}Lordaeron{/link} über das Meer kamen. Im Westen drängen sich die {link:ogres}Oger{/link} des Stonemaulclans in einem Dorf aus Hütten zwischen dem Schilf. Und im fernen Süden, wo das Moor zu versengtem Fels wird, nisten schwarze Drachen im {link:wyrmbog}Drachensumpf{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer den {link:the-marshlands}Marschen{/link} zuerst ihren Namen gab oder welche Völker vor dem {link:third-war}Dritten Krieg{/link} an ihren Ufern wandelten. Erzählt wird, dass {link:jaina-proudmoore}Jaina Proudmoore{/link} die Überlebenden der nördlichen Königreiche über das Meer nach {link:kalimdor}Kalimdor{/link} führte. Nach der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} wählte sie eine Insel vor der Küste dieses Sumpfes als ihre neue Heimat und errichtete darauf {link:theramore-isle}Theramore{/link}. Dort wahrte sie den Frieden, den sie mit {link:thrall}Thrall{/link} geschlossen hatte. Als ihr Vater, Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link}, mit seiner Flotte kam, um die {link:orcs}Orcs{/link} zu vernichten, erreichte der Krieg die Tore von Theramore, und der Admiral starb vor seinen Mauern. Seine Tochter stand ihm nicht bei.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:theramore-isle}Theramore{/link} steht, doch die {link:the-marshlands}Marschen{/link} um die Stadt gehören ihr nicht. Ihre Soldaten halten einige Türme, aber sie haben die Kontrolle über die Straßen verloren. Einige der Marinesoldaten, die mit der Flotte der Proudmoores kamen, sind lieber desertiert, als einer Herrin zu dienen, die mit {link:orcs}Orcs{/link} Frieden schloss. Spione der {link:horde}Horde{/link} beobachten die Stadt aus dem Schilf, und Theramores eigene Späher beobachten die Horde. Das {link:shady-rest-inn}Gasthaus Zur süßen Ruh{/link} an der westlichen Straße ist bis auf die Grundmauern niedergebrannt, und niemand weiß, durch wessen Hand. Selbst die Treue der Stadt hat Risse: Ein Soldat von Theramore wurde im Bund mit der {link:defias-brotherhood}Bruderschaft der Defias{/link} gegen den König von {link:stormwind-city}Stormwind{/link} selbst gefunden.

Im Westen sind die {link:ogres}Oger{/link} der Stonemaul aus ihrem alten Dorf im Süden geflohen. {link:rexxar}Rexxar{/link} machte einst {link:overlord-mok-morokk}Mok'Morokk{/link} zu ihrem Oberherrn, und Mok'Morokk ist in seinem Amt fett geworden. Im Süden hat die Brut von {link:onyxia}Onyxia{/link}, der Tochter von {link:deathwing}Todesschwinge{/link}, den {link:wyrmbog}Drachensumpf{/link} in Besitz genommen, und ihre Eier liegen über das Drachendüster verstreut.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Das Volk von {link:theramore-isle}Theramore{/link}.{/b} Soldaten, Marinesoldaten aus {link:kul-tiras}Kul Tiras{/link}, Magier, Schmiede und Händler, die mit {link:jaina-proudmoore}Lady Proudmoore{/link} über das Meer kamen.
• {b}Die {link:horde}Horde{/link}.{/b} Agenten der {link:orcs}Orcs{/link} und {link:ogres}Oger{/link} in {link:brackenwall-village}Brackenwall{/link}, die Theramore und die Straßen beobachten.
• {b}Die Oger der Stonemaul.{/b} Vom schwarzen Drachenschwarm aus ihrer Heimat nach Norden vertrieben.
• {b}Der schwarze Drachenschwarm.{/b} Drachkin, Welpen und Drachen der Firemane und der sengenden Brut, die {link:onyxia}Onyxia{/link} im Süden dienen.
• {b}Deserteure.{/b} Ehemalige Soldaten von Theramore, die sich in verlassenen Türmen eingenistet haben.
• {b}Die Wildnis.{/b} Krokilisken, Spinnen, Schlammbestien, Krabbenwesen der Muckshell, {link:murlocs}Murlocs der Mirefin{/link} und die {link:naga}Naga der Strashaz{/link} auf der {link:alcaz-island}Insel Alcaz{/link}.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der Exodus.{/b} {link:jaina-proudmoore}Jaina Proudmoore{/link} führte die Überlebenden von {link:lordaeron}Lordaeron{/link} westwärts über das Meer nach {link:kalimdor}Kalimdor{/link}.
• {b}{link:theramore-isle}Theramore{/link}.{/b} Nach Hyjal bauten die Flüchtlinge ihre Stadt auf ihrer Insel, und viele von Daelins Marinesoldaten traten in ihre Wache ein.
• {b}Der Krieg des Admirals.{/b} {link:daelin-proudmoore}Daelin Proudmoore{/link} führte Krieg gegen die {link:horde}Horde{/link} und fiel vor Theramore.
• {b}Die Stonemaul.{/b} {link:rexxar}Rexxar{/link} führte die Stonemaul eine Zeit lang. Als er ging, herrschte {link:overlord-mok-morokk}Mok'Morokk{/link} in seinem Namen.]=],
		},
		{
			title = "Legenden der Marschen",
			text = [=[• Die Wache von {link:theramore-isle}Theramore{/link} trägt ein Abzeichen mit einem goldenen Anker auf Weiß. Es ist das Zeichen der Stadt.
• Eine Einsiedlerin namens {link:tabetha}Tabetha{/link} bewohnt eine Hütte tief in den {link:the-marshlands}Marschen{/link}, und Magier und Hexenmeister suchen sie auf.
• Auf einer Insel südlich von Theramore lebt ein Fischer, der sagt, das Fischen habe ihm nie sonderlich Freude gemacht.]=],
		},
	},
})

Translate("deDE", "theramore-isle", {
	title = "Die Insel Theramore",
	aliases = { "Theramore", "Stadt Theramore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Theramore ist die Stadt von Lady {link:jaina-proudmoore}Jaina Proudmoore{/link}, errichtet auf einer Insel in der Bucht der {link:dustwallow-marsh}Marschen von Dustwallow{/link}. Ihre weißen Mauern und blauen Dächer beherbergen die Flüchtlinge aus {link:lordaeron}Lordaeron{/link} und die Marinesoldaten aus {link:kul-tiras}Kul Tiras{/link}, die an der Seite ihrer Herrin blieben. Die Foothold-Zitadelle beherbergt ihre Kaserne und ihre Offiziere, und ein hoher Turm dient der Herrin selbst als Sitz. Schiffe segeln von ihren Docks über das Meer zum {link:menethil-harbor}Hafen von Menethil{/link}. Theramore ist eine Stadt der {link:alliance}Allianz{/link}, doch ihre Herrin hält Frieden mit der {link:horde}Horde{/link}. Dieser Frieden wird nicht von allen geliebt, die in ihren Mauern leben.]=],
		},
	},
})

Translate("deDE", "brackenwall-village", {
	title = "Brackenwall",
	aliases = { "Dorf Brackenwall" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Brackenwall ist ein Lager der {link:horde}Horde{/link} aus Hütten und Palisaden in den westlichen {link:the-marshlands}Marschen{/link}, nahe der Straße ins {link:the-barrens}Brachland{/link}. Es ist die Heimat der {link:ogres}Oger{/link} der Stonemaul, die hierher flohen, als schwarze Drachen ihr altes Dorf im Süden niederbrannten. {link:overlord-mok-morokk}Oberherr Mok'Morokk{/link} beherrscht die Oger von seiner Mitte aus und hat keinerlei Wunsch fortzugehen. Auch Agenten der {link:orcs}Orcs{/link} halten hier ihre Posten: ein Meisterspion, der {link:theramore-isle}Theramore{/link} beobachtet, und ein Krieger, der die Wahrheit über den Brand des Gasthauses {link:shady-rest-inn}Zur süßen Ruh{/link} sucht.]=],
		},
	},
})

Translate("deDE", "stonemaul-ruins", {
	title = "Die Stonemaul Ruinen",
	aliases = { "Dorf der Stonemaul" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Stonemaul Ruinen waren die Heimat der {link:ogres}Oger{/link} der Stonemaul, bis der schwarze Drachenschwarm kam. Drachkin der Firemane und Schwärme sengender Welpen halten nun ihre verbrannten Hütten, und die nahe Höhle, die man den Flammenbau nennt, brennt von ihren Feuern. Die Oger flohen so schnell, dass ihr Oberherr seinen Grog, seinen Schnupftabak und seine Geldkassette zurückließ. Der alte {link:tharg}Tharg{/link} nennt diese Ruinen noch immer seine Heimat, und er träumt davon, sie zurückzuerobern. {link:draz-zilb}Draz'Zilb{/link} glaubt, dass die Drachen aus einem größeren Grund kamen, als eine kleine Schar Oger zu vertreiben.]=],
		},
	},
})

Translate("deDE", "wyrmbog", {
	title = "Der Drachensumpf",
	aliases = { "Drachensumpf", "Das Drachendüster" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Drachensumpf ist der äußerste Süden der {link:dustwallow-marsh}Marschen von Dustwallow{/link}, wo der Sumpf versengtem Stein weicht. Hier nistet der schwarze Drachenschwarm. Die Eier von {link:onyxia}Onyxia{/link} liegen über das Moor verstreut, das man das Drachendüster nennt, und ihre Brut bewacht sie. In einer eigenen Höhle haust der uralte Drache {link:emberstrife}Emberstrife{/link}. Tief im Sumpf öffnet sich die Höhle von {link:onyxias-lair}Onyxias Hort{/link}, wo die Brutmutter auf ihrem Schatz schlafen soll. Wenige, die dorthin gehen, kehren zurück, um davon zu erzählen.]=],
		},
	},
})

Translate("deDE", "shady-rest-inn", {
	title = "Gasthaus Zur süßen Ruh",
	aliases = { "Zur süßen Ruh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Gasthaus Zur süßen Ruh stand an der westlichen Straße der {link:dustwallow-marsh}Marschen von Dustwallow{/link}, nahe der Grenze zum {link:the-barrens}Brachland{/link}. Ein Mann namens {link:smiling-jim}James Hyal{/link} baute es, um Reisenden ein sicheres Dach zu geben, und eine Zeit lang ging es gut. Dann entglitten die Straßen Theramores Kontrolle, und Hyal wollte nicht fortgehen. Nun sind nur noch ein rauchendes Gerippe und ein bröckelnder Schornstein übrig. In der Asche liegen ein geschwärzter Schild, ein Abzeichen von {link:theramore-isle}Theramore{/link} und Reihen von Hufabdrücken im Schlamm. Hyals Frau und Kind starben im Feuer.]=],
		},
	},
})

Translate("deDE", "swamplight-manor", {
	title = "Swamplight-Anwesen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Swamplight-Anwesen ist ein einsames Haus auf dem Hexenhügel im Norden der {link:the-marshlands}Marschen{/link}. Sein einziger Bewohner ist ein seltsamer Mann namens {link:swamp-eye-jarl}"Swamp Eye" Jarl{/link}, der Eintöpfe aus Froschschenkeln kocht und den Saft von Spinnenaugen trinkt. Er bleibt für sich, und den meisten Reisenden ist das recht. Nur wenige Schritte vor seiner Tür verbarg lockere Erde einst die Hand und den Kopf eines ermordeten Spions der {link:orcs}Orcs{/link}. Keine Chronik verzeichnet, wer das Anwesen baute oder was aus seinen ersten Herren wurde.]=],
		},
	},
})

Translate("deDE", "sentry-point", {
	title = "Späherwacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Späherwacht ist der erste Turm von {link:theramore-isle}Theramore{/link} an der Straße in die {link:the-marshlands}Marschen{/link}, an der Küste nordwestlich der Stadt. Ein Hauptmann und eine kleine Schar Wachen halten ihn. Er überwacht den Damm nach Theramore und den Sumpf dahinter. Jenseits davon führt die Straße westwärts in Länder, die Theramore nicht mehr beherrscht. Hier sollte der Soldat {link:private-hendel}Hendel{/link} stationiert sein, und hier begann die Suche nach ihm.]=],
		},
	},
})

Translate("deDE", "north-point-tower", {
	title = "Nordwacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nordwacht ist ein Außenposten von {link:theramore-isle}Theramore{/link} in den nördlichen {link:the-marshlands}Marschen{/link}, an der Straße, die westwärts zum {link:the-barrens}Brachland{/link} führt. Wachposten bewachen Zelte entlang der Straße, in denen Theramores Späher zwischen ihren Einsätzen ruhen. Von hier aus schleichen die Späher ins Schilf, um {link:brackenwall-village}Brackenwall{/link} auszukundschaften. Raptoren und Krokilisken jagen im Land ringsum, und die Wachposten behalten das Schilf im Auge. Der Gefreite {link:private-hendel}Hendel{/link} hielt Wache über dieses Lager, und die {link:horde}Horde{/link} hat eigene Jäger geschickt, um die Spione vor ihrer Haustür zu beseitigen.]=],
		},
	},
})

Translate("deDE", "lost-point", {
	title = "Die verlassene Wacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die verlassene Wacht ist ein aufgegebener Turm von {link:theramore-isle}Theramore{/link} südöstlich des Gasthauses {link:shady-rest-inn}Zur süßen Ruh{/link}. Theramore konnte ihn nicht mehr halten, und Deserteure haben ihn für sich genommen. Es sind ehemalige Soldaten der Stadt, angeführt von einem Mann namens {link:balos-jacken}Balos Jacken{/link}. Sie wollen nur vergessen werden, doch sie wissen mehr über die {link:the-marshlands}Marschen{/link} als die Wachen, die einst an ihrer Seite dienten. {link:captain-garran-vimes}Hauptmann Vimes{/link} hat Leutnant Caldwell geschickt, um sich um sie zu kümmern.]=],
		},
	},
})

Translate("deDE", "darkmist-cavern", {
	title = "Graunebelhöhlen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Graunebelhöhlen öffnen sich im Nordwesten der {link:the-marshlands}Marschen{/link}. Sie sind ein Nest großer Spinnen: der Einsiedler, Seidenspinner und Witwen der Darkmist, die ihre Netze über den Eingang spannen. Reisende gehen rasch an ihnen vorbei. {link:swamp-eye-jarl}"Swamp Eye" Jarl{/link} sieht den Ort anders. Er schätzt die Augen seiner Spinnen, und er mag sie unzerplatzt. Ob die Spinnen nach der Höhle benannt wurden oder die Höhle nach den Spinnen, kann nicht einmal Jarl sagen.]=],
		},
	},
})

Translate("deDE", "alcaz-island", {
	title = "Insel Alcaz",
	aliases = { "Alcaz" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Insel Alcaz liegt vor der Nordostküste der {link:dustwallow-marsh}Marschen von Dustwallow{/link}, {link:theramore-isle}Theramore{/link} gegenüber jenseits des Wassers. Die {link:naga}Naga{/link} der Strashaz halten sie: Krieger, Sirenen, Zauberinnen und große Hydren, die sich im seichten Wasser winden. Niemand in Theramore spricht darüber, warum die Naga der Stadt so nahe gekommen sind oder was sie auf ihrer Insel bewachen. Die Hydren der Naga jagen in den Gewässern zwischen der Insel und dem nördlichen Ufer, und die Seeleute der Bucht halten sich fern.]=],
		},
	},
})

Translate("deDE", "archmage-tervosh", {
	title = "Erzmagier Tervosh",
	subtitle = "Erzmagier von Theramore",
	found = "Der Turm von Lady Proudmoore, Insel Theramore",
	hint = [=[Sprecht mit dem Erzmagier, der im Turm von Lady Proudmoore dient.]=],
	allegiance = "Theramore",
	aliases = { "Tervosh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzmagier Tervosh ist ein Magier von {link:theramore-isle}Theramore{/link} und ein vertrauter Diener von {link:jaina-proudmoore}Jaina Proudmoore{/link}. Er hält sich im Turm der Herrin auf, wo er das Arkane studiert und in Angelegenheiten für sie handelt, die für Soldaten zu heikel sind. Als die Nachricht kam, dass ein Soldat von Theramore den König von {link:stormwind-city}Stormwind{/link} verraten hatte, war es Tervosh, den die Herrin schickte, um für Gerechtigkeit zu sorgen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tervosh ist die stille Hand von {link:theramore-isle}Theramore{/link}. Die Herrin kann nicht immer offen handeln, und ihr Erzmagier geht, wohin sie nicht gehen kann. Seine Studien seltsamer Kristalle reichen zudem weit über die {link:the-marshlands}Marschen{/link} hinaus, bis zum zerstörten Tempel von {red:maraudon}Maraudon{/red} in {link:desolace}Desolace{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er nahm auf Befehl von {link:jaina-proudmoore}Lady Proudmoore{/link} die Suche nach dem Gefreiten {link:private-hendel}Hendel{/link} auf.
• Er kam denen zu Hilfe, die Hendel stellten, damit der Verräter weder entkam noch starb, bevor man ihn verhören konnte.
• Er brachte Hendel zum Verhör nach {link:theramore-isle}Theramore{/link} zurück.
• Er studiert die purpurnen Kristalle, die er Schattensplitter nennt, genommen von den Elementaren von Maraudon.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Tervosh' Leben vor {link:theramore-isle}Theramore{/link} geschrieben. Keine Chronik verzeichnet, wo er seine Kunst erlernte.]=],
		},
	},
	chapters = {
		{
			title = "Der Verräter von Theramore",
			hint = "Sucht auf den Straßen der Marschen nach dem Soldaten Hendel.",
			text = [=[Die Spur des entführten Königs führte vom Hafen von Menethil zu einem einzigen Namen: {link:private-hendel}Hendel{/link}, ein Gefreiter von {link:theramore-isle}Theramore{/link}. Als die Suchenden zur {link:sentry-point}Späherwacht{/link} kamen, war Hendel nicht dort. Tervosh war es. {link:jaina-proudmoore}Lady Proudmoore{/link} hatte bereits erfahren, was sie wussten, und ihren Erzmagier geschickt, um sie zu treffen. Er sagte ihnen, wo Hendel Wache stand, und versprach zu folgen.]=],
		},
		{
			title = "Gerechtigkeit bei den Zelten",
			hint = "Stellt den Gefreiten Hendel zur Rede.",
			text = [=[{link:private-hendel}Hendel{/link} wartete nicht darauf, ein zweites Mal beschuldigt zu werden. Er zog sein Schwert. Als der Kampf vorüber war, war Tervosh zur Stelle. Der Erzmagier ließ Hendel weder fliehen noch sterben. Er brachte den Verräter nach {link:theramore-isle}Theramore{/link} zurück, um zu erfahren, was er über den König wusste. Tervosh verbarg seine Bestürzung nicht. Der König von {link:stormwind-city}Stormwind{/link} war verschwunden, und einer von Theramores eigenen Leuten hatte geholfen, ihn zu entführen.]=],
		},
	},
	mentions = {
		{
			text = [=[The Missing Diplomat, an der {link:sentry-point}Späherwacht{/link}]=],
		},
		{
			text = [=[The Missing Diplomat, ausgesandt, um {link:private-hendel}Hendel{/link} zu finden]=],
		},
		{
			text = [=[The Missing Diplomat, {link:private-hendel}Hendel{/link} überwältigt]=],
		},
		{ text = "The Missing Diplomat, zur Herrin" },
		{ text = "Shadowshard Fragments" },
	},
	bonds = {
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "seine Herrin" },
		{ id = "private-hendel", name = "Gefreiter Hendel", note = "der Verräter, den er gefangen nahm" },
		{ id = "commander-samaul", name = "Kommandant Samaul", note = "befehligt die Truppen der Herrin" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "der verschwundene König" },
	},
})

Translate("deDE", "captain-garran-vimes", {
	title = "Hauptmann Garran Vimes",
	subtitle = "Hauptmann der Wache von Theramore",
	found = [=[Das oberste Stockwerk der Foothold-Zitadelle, Insel Theramore]=],
	hint = [=[Steigt in der Foothold-Zitadelle hinauf und sprecht mit dem Hauptmann der Wache.]=],
	allegiance = "Theramore · Wache von Theramore",
	aliases = { "Garran Vimes", "Hauptmann Vimes" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Garran Vimes befehligt die Wache von {link:theramore-isle}Theramore{/link} vom obersten Stockwerk der Foothold-Zitadelle aus. Jeder Bericht aus den {link:the-marshlands}Marschen{/link} landet auf seinem Schreibtisch: Spione im Schilf, Deserteure in den Türmen, ein niedergebranntes Gasthaus an der westlichen Straße. Er liest Orcisch besser als die meisten Männer der Stadt, und er traut Tatsachen mehr als Gerüchten. Er hat nicht genug Soldaten, und er sagt es offen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vimes hält die Grenze Theramores gegen Feinde von außen und Zweifel von innen. {link:the-marshlands}Die Marschen{/link} entgleiten seinem Griff, und einige seiner eigenen Soldaten haben sich um des toten Admirals willen gegen die Stadt gewandt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er liest die Berichte über Spione der {link:horde}Horde{/link}, die nahe {link:theramore-isle}Theramore{/link} gefunden wurden.
• Er leitet die Untersuchung des Brandes im {link:shady-rest-inn}Gasthaus Zur süßen Ruh{/link}.
• Er schickte den Fährtenleser Falgran Hastil den Hufabdrücken nach, die vom Gasthaus wegführten.
• Er schickte Leutnant Caldwell, um sich um die Deserteure der verlassenen Wacht zu kümmern.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Vimes' Leben vor {link:theramore-isle}Theramore{/link} geschrieben.]=],
		},
	},
	chapters = {
		{
			title = "Der Bericht der Orcs",
			hint = [=[Bringt dem Hauptmann einen auf Orcisch geschriebenen Bericht.]=],
			text = [=[Ein Bericht auf Orcisch, gefunden in der Hand eines toten {link:orcs}Orcs{/link}, gelangte über seine Leutnants zu Vimes. Er las ihn selbst. Er bestätigte, was er lange vermutet hatte. Die {link:horde}Horde{/link} hatte Spione, die {link:theramore-isle}Theramore{/link} beobachteten, und sie waren schon seit Wochen dort.]=],
		},
		{
			title = "Das niedergebrannte Gasthaus",
			hint = "Durchsucht die Trümmer des Gasthauses Zur süßen Ruh.",
			text = [=[{link:smiling-jim}James Hyal{/link} wollte sein Gasthaus nicht aufgeben, als die Straßen verloren gingen, und die Süße Ruh brannte. Vimes hatte ermittelt und wenig gefunden. Dann kamen Beweise aus der Asche: Hufabdrücke im Schlamm und ein schlichter eiserner Schild, der auf den Schornstein gesetzt war. Der Schmied Caz Twosprocket sagte, der Schild sei nicht auf dieser Seite des Meeres geschmiedet worden, und sein Riemen sei für jemanden sehr Großen gemacht, vielleicht einen {link:tauren}Tauren{/link}. Es war nicht viel. Vimes behielt es im Gedächtnis.]=],
		},
		{
			title = "Daelins Männer",
			hint = "Erfahrt das Schicksal von Leutnant Paval Reethe.",
			text = [=[Ein Abzeichen von {link:theramore-isle}Theramore{/link} in der Asche trug den Namen von {link:paval-reethe}Leutnant Paval Reethe{/link}. Die Akten führten ihn als vermisst. Vimes nannte ihn, was er war: einen Mann, der Admiral {link:daelin-proudmoore}Daelin{/link} so treu ergeben war, dass er zum Verräter wurde. Er fand darin eine bittere Ironie. Die Deserteure warfen Theramore vor, die {link:alliance}Allianz{/link} verraten zu haben.]=],
		},
	},
	mentions = {
		{ text = "Captain Vimes" },
