			title = "Zusammenfassung",
			text = [=[Kommandant Samaul führt die Truppen von Lady {link:jaina-proudmoore}Jaina Proudmoore{/link} in {link:theramore-isle}Theramore{/link}. Er ist ein vielbeschäftigter Mann, aber ein höflicher. Er warnt jeden Neuankömmling, dass die {link:the-marshlands}Marschen{/link} jenseits der Mauern voller {link:ogres}Oger{/link}, {link:orcs}Orcs{/link}, {link:murlocs}Murlocs{/link} und schwarzer Drachen sind. Er ist vor allem anderen seiner Herrin treu.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Samaul stand zwischen der Stadt und der Suche nach dem Verräter {link:private-hendel}Hendel{/link}. Er wollte keinen seiner Soldaten ausliefern, ohne den Grund zu kennen, und er vertraute darauf, dass seine Herrin richten würde.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sagte den Suchenden, dass {link:private-hendel}Hendel{/link} an der {link:sentry-point}Späherwacht{/link} stationiert sei.
• Er bat, von jeder Bedrohung unterrichtet zu werden, die Theramores Ländern drohen könnte.]=],
		},
	},
	mentions = {
		{ text = "The Missing Diplomat" },
		{ text = "The Missing Diplomat" },
	},
	bonds = {
