	},
})

Translate("deDE", "private-hendel", {
	title = "Gefreiter Hendel",
	subtitle = "Verräter von Theramore",
	found = "Die Zelte nahe der Nordwacht",
	hint = [=[Findet den Gefreiten, der über die Zelte der Späher Wache hält.]=],
	allegiance = "Theramore (abtrünnig) · Bruderschaft der Defias",
	aliases = { "Hendel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hendel war ein Gefreiter von {link:theramore-isle}Theramore{/link}, einer der Marinesoldaten aus {link:kul-tiras}Kul Tiras{/link}, die zu Beginn jedes Monats ihren Sold erhielten und ihn in den Tavernen des {link:menethil-harbor}Hafens von Menethil{/link} ausgaben. Er hielt Wache über die Zelte der Späher von Theramore an der nördlichen Straße. Er war auch der Mann, den die {link:defias-brotherhood}Bruderschaft der Defias{/link} gekauft hatte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hendel war das Bindeglied zwischen den {link:defias-brotherhood}Defias{/link} und dem Schiff, das den König von {link:stormwind-city}Stormwind{/link} in Richtung {link:theramore-isle}Theramore{/link} trug. Sein Verrat bewies, dass die Verschwörung gegen den König bis in die Wache von {link:jaina-proudmoore}Lady Proudmoore{/link} reichte.]=],
		},
	},
	chapters = {
		{
			title = "Die Anklage",
			hint = "Konfrontiert Hendel mit dem, was Ihr wisst.",
			text = [=[Beschuldigt, mit den {link:defias-brotherhood}Defias{/link} gemeinsame Sache zu machen, geriet Hendel in Wut und zog blank. Er verlor. {link:archmage-tervosh}Erzmagier Tervosh{/link} ließ ihn weder fliehen noch sterben. Er wurde in die Stadt zurückgebracht, um sich für den König zu verantworten.]=],
		},
	},
	mentions = {
		{ text = "The Missing Diplomat" },
		{ text = "The Missing Diplomat" },
	},
	bonds = {
		{ id = "archmage-tervosh", name = "Erzmagier Tervosh", note = "nahm ihn gefangen" },
		{ id = "commander-samaul", name = "Kommandant Samaul", note = "sein Kommandant" },
		{ id = "tapoke-slim-jahn", name = "Tapoke \"Slim\" Jahn", note = "half, ihn an Bord zu bringen" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "der König, den er verriet" },
	},
})

Translate("deDE", "adjutant-tesoran", {
