		},
		{
			title = "Taten",
			text = [=[• Er fand die Akte von {link:paval-reethe}Leutnant Paval Reethe{/link}: Marinesoldat aus {link:kul-tiras}Kul Tiras{/link} seit seinem sechzehnten Lebensjahr, ein Mann mit ausgezeichnetem Dienst, nun vermisst.]=],
		},
	},
	mentions = {
		{ text = "Lieutenant {link:paval-reethe}Paval Reethe{/link}" },
