	},
	bonds = {
		{ id = "captain-garran-vimes", name = "Hauptmann Garran Vimes", note = "sein Hauptmann" },
		{ id = "paval-reethe", name = "Paval Reethe", note = "der Name in seinen Büchern" },
	},
})

Translate("deDE", "smiling-jim", {
	title = "Smiling Jim",
	subtitle = "Der Wirt der Süßen Ruh",
	found = "Nahe dem Gasthaus der Insel Theramore",
	hint = [=[Sucht den gebrochenen Mann, den die Wachen von Theramore Smiling Jim nennen.]=],
	allegiance = "Theramore",
	aliases = { "James Hyal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[James Hyal kam mit {link:jaina-proudmoore}Lady Proudmoore{/link} über das Meer und baute das {link:shady-rest-inn}Gasthaus Zur süßen Ruh{/link} am Rand der {link:the-marshlands}Marschen{/link}. Sein Bruder in Menethil erinnert sich an ihn als einen vortrefflichen Koch. Hyal wollte sein Gasthaus nicht verlassen, als die Straßen gefährlich wurden. Es brannte, und seine Frau und sein Kind starben mit ihm. Nun wandert er durch {link:theramore-isle}Theramore{/link}, und die Wachen nennen ihn Smiling Jim.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hyals Trauer ist das Herz des Rätsels um die Süße Ruh. Sowohl {link:theramore-isle}Theramore{/link} als auch {link:brackenwall-village}Brackenwall{/link} suchen jene, die sein Gasthaus niederbrannten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er baute das {link:shady-rest-inn}Gasthaus Zur süßen Ruh{/link}, um Reisenden einen sicheren Ort in den {link:the-marshlands}Marschen{/link} zu geben.]=],
		},
	},
	mentions = {
		{ text = "They Call Him Smiling Jim" },
		{ text = "James Hyal" },
		{ text = "James Hyal" },
	},
	bonds = {
		{ id = "captain-garran-vimes", name = "Hauptmann Garran Vimes", note = "untersucht den Brand" },
	},
})

Translate("deDE", "paval-reethe", {
	title = "Paval Reethe",
	subtitle = "Deserteur von Theramore",
	found = "Versteckt im Schilf östlich von Brackenwall",
	hint = [=[Findet den Deserteur, der sich allein im Schilf der Marschen versteckt.]=],
	allegiance = "Theramore (Deserteur)",
	aliases = { "Reethe", "Leutnant Paval Reethe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Paval Reethe war ein Leutnant von {link:theramore-isle}Theramore{/link} und seit seinem sechzehnten Lebensjahr ein Marinesoldat aus {link:kul-tiras}Kul Tiras{/link}. Er desertierte. Die anderen Deserteure der verlassenen Wacht stießen ihn aus, als er immer wieder die Vorräte der {link:ogres}Oger{/link} von {link:brackenwall-village}Brackenwall{/link} plünderte. Sein Abzeichen wurde in der Asche des Gasthauses {link:shady-rest-inn}Zur süßen Ruh{/link} gefunden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Reethe ist ein Faden im Rätsel um die Süße Ruh und ein Zeichen dafür, wie tief die Getreuen des Admirals gefallen sind.]=],
		},
	},
	chapters = {
		{
			title = "Das Verhör von Reethe",
			hint = "Geht mit dem Fährtenleser Ogron, um Reethe zu finden.",
			text = [=[{link:ogron}Ogron{/link} aus {link:brackenwall-village}Brackenwall{/link} fand Reethe im Sumpf versteckt. Als sie kamen, um ihn zu befragen, endete die Begegnung in Blut. Ein Pfeil traf den Deserteur, und er erholte sich nicht. Was immer er über das niedergebrannte Gasthaus wusste, starb mit ihm.]=],
		},
	},
	mentions = {
		{ text = "Lieutenant Paval Reethe" },
