	allegiance = "Theramore",
	aliases = { "Fiora" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fiora Longears ist eine Elfe, die jene empfängt, die auf dem Seeweg nach {link:theramore-isle}Theramore{/link} kommen. Ihr Partner, Red Jack Flint, schickt ihr die mutigen Seelen, die er im {link:menethil-harbor}Hafen von Menethil{/link} findet. Sie erzählt ihnen von {link:kalimdor}Kalimdor{/link} und weist ihnen den Weg nach {link:astranaar}Astranaar{/link} und in die Länder dahinter. Sie kauft auch das Gift wilder Wyvern, das manche höher schätzen als die Tiere selbst.]=],
