		{
			title = "Bedeutung",
			text = [=[Fiora ist die erste Freundin, die viele Reisende in {link:kalimdor}Kalimdor{/link} finden. Durch sie und ihren Partner sind die Häfen der beiden Kontinente durch mehr als nur Schiffe verbunden.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Neuankömmlinge nach Norden zu den {link:night-elves}Nachtelfen{/link} von {link:astranaar}Astranaar{/link}.
• Sie bezahlt für das Gift der Wyvern vom Steilhang in {link:thousand-needles}Tausend Nadeln{/link}.]=],
		},
	},
	mentions = {
		{ text = "Fiora Longears" },
		{ text = "Journey to {link:astranaar}Astranaar{/link}" },
		{ text = "Highperch Venom" },
	},
})

Translate("deDE", "nat-pagle", {
