	},
})

Translate("deDE", "overlord-mok-morokk", {
	title = "Oberherr Mok'Morokk",
	subtitle = "Oberherr der Stonemaul",
	found = "Brackenwall",
	hint = [=[Verneigt Euch vor dem Oberherrn der Stonemaul in Brackenwall.]=],
	allegiance = "Oger der Stonemaul · Horde",
	aliases = { "Mok'Morokk" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oberherr Mok'Morokk beherrscht die {red:stonemaul-ogres}Oger der Stonemaul{/red} von {link:brackenwall-village}Brackenwall{/link} aus. {link:rexxar}Rexxar{/link} machte ihn zum Oberherrn, und Mok'Morokk lässt es niemanden je vergessen. Als schwarze Drachen das {link:stonemaul-ruins}Dorf der Stonemaul{/link} im Süden niederbrannten, führte er sein Volk nach Norden ins Schilf. Er nennt das Weisheit. Viele seiner {link:ogres}Oger{/link} nennen es Weglaufen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mok'Morokk zeigt, was Macht aus einem Anführer machen kann, über den niemand wacht. Er war stark, solange {link:rexxar}Rexxar{/link} den Clan führte. Nachdem Rexxar gegangen war, begann er Dienste zu verlangen, statt sie zu leisten, und sein Volk begann sich gegen ihn zu wenden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die Stonemaul aus ihrem alten Dorf, als die schwarzen Drachen kamen.
• Er schickte andere zu den Ruinen zurück, um den Grog, den Schnupftabak und die Geldkassette zu holen, die er zurückgelassen hatte.
• Er weigerte sich, gegen die Brut von {link:onyxia}Onyxia{/link} zu den Waffen zu greifen.]=],
		},
	},
	chapters = {
		{
			title = "Die Habseligkeiten des Oberherrn",
			hint = "Holt zurück, was der Oberherr im Süden zurückließ.",
			text = [=[Mok'Morokk verließ seine Heimat in solcher Eile, dass er die Dinge vergaß, die er am meisten liebte. Er ging nicht selbst zurück, um sie zu holen. Er sei zu sehr mit Führen beschäftigt, sagte er. Also gingen andere nach Süden in das Feuer der Stonemaul Ruinen und des Flammenbaus und brachten seinen Grog, seinen Schnupftabak und seine Schatzkiste zurück.]=],
		},
		{
			title = "Die Herausforderung",
			hint = "Fordert den Oberherrn in seinem eigenen Dorf heraus.",
			text = [=[{link:draz-zilb}Draz'Zilb{/link} hatte entschieden, dass der Clan einen neuen Anführer brauchte. Als der Oberherr in {link:brackenwall-village}Brackenwall{/link} herausgefordert wurde, lachte er und versprach eine Tracht Prügel. Er verlor. Der mächtige Oberherr der Stonemaul floh wie ein verängstigtes Kind aus seinem eigenen Dorf, und die {link:ogres}Oger{/link} begannen davon zu sprechen, einen Anführer zu wählen, der sie heimführen würde.]=],
		},
	},
	mentions = {
		{ text = "Overlord Mok'Morokk's Concern" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "The Brood of {link:onyxia}Onyxia{/link}" },
		{ text = "Challenge Overlord Mok'Morokk" },
	},
